import java.util.*;
import java.text.*;

public class Check {
    public static void main(String[] args) throws Exception {
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Calendar cal = new GregorianCalendar(utc, Locale.US);
        cal.clear();
        cal.set(2023, Calendar.JANUARY, 2, 3, 4, 5);
        cal.set(Calendar.MILLISECOND, 6);
        System.out.println("DAY_OF_WEEK=" + cal.get(Calendar.DAY_OF_WEEK) + " (2=Monday)");
        System.out.println("DAY_OF_YEAR=" + cal.get(Calendar.DAY_OF_YEAR));

        Calendar cal2 = new GregorianCalendar(utc, Locale.US);
        cal2.clear();
        cal2.set(2023, Calendar.DECEMBER, 31, 0, 0, 0);
        System.out.println("Dec31 DAY_OF_YEAR=" + cal2.get(Calendar.DAY_OF_YEAR) + " DAY_OF_WEEK=" + cal2.get(Calendar.DAY_OF_WEEK));

        Calendar cal3 = new GregorianCalendar(utc, Locale.US);
        cal3.clear();
        cal3.set(2005, Calendar.JULY, 15, 12, 0, 0);
        System.out.println("2005 YEAR mod100 test via SDF");
        SimpleDateFormat sdf = new SimpleDateFormat("yy", Locale.US);
        sdf.setTimeZone(utc);
        System.out.println("yy(2005)=" + sdf.format(cal3.getTime()));

        SimpleDateFormat sdfY = new SimpleDateFormat("YYYY", Locale.US);
        sdfY.setTimeZone(utc);
        SimpleDateFormat sdfy = new SimpleDateFormat("yyyy", Locale.US);
        sdfy.setTimeZone(utc);
        System.out.println("mid-year YYYY=" + sdfY.format(cal3.getTime()) + " yyyy=" + sdfy.format(cal3.getTime()));

        // midnight UTC for hour fields
        Calendar midnight = new GregorianCalendar(utc, Locale.US);
        midnight.clear();
        midnight.set(2023, Calendar.JANUARY, 2, 0, 0, 0);
        System.out.println("HOUR=" + midnight.get(Calendar.HOUR) + " HOUR_OF_DAY=" + midnight.get(Calendar.HOUR_OF_DAY));
    }
}
